const $=s=>document.querySelector(s), axes=['x','y','z','Tx','Ty','Tz'], key='optdsh-tx-design-draft-v3';
const objects=[{id:101,name:'示例准直镜 A',type:'Standard Lens',role:'lens'},{id:102,name:'示例整形镜 B',type:'Aspheric Lens',role:'lens'},{id:103,name:'示例扩束镜 C',type:'Standard Lens',role:'lens'},{id:201,name:'示例四 die 耦合基准',type:'Null Object · 四颗 die 的公共父坐标',role:'group'},{id:211,name:'示例 die1',type:'Source Diode',role:'source'},{id:212,name:'示例 die2',type:'Source Diode',role:'source'},{id:213,name:'示例 die3',type:'Source Diode',role:'source'},{id:214,name:'示例 die4',type:'Source Diode',role:'source'},{id:301,name:'示例 die1 专用探测面',type:'Detector Rectangle',role:'detector'},{id:302,name:'示例 die2 专用探测面',type:'Detector Rectangle',role:'detector'}];
const names=['装配配置','目标','运行与结果'], descriptions=['盲装 / 耦合','die1 / die2 · 探测面','灵敏度 / Monte Carlo'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const objectLabel=id=>{const o=objects.find(o=>o.id===+id);return o?`OBJ${o.id}[${o.name}]`:'待选择';};
function makePart(ids,kind){return {id:crypto.randomUUID(),objects:ids,kind,axes:[...axes],sigma:Object.fromEntries(axes.map(a=>[a,a.length===1?.02:.05])),ranges:Object.fromEntries(axes.map(a=>[a,a.length===1?[-.04,.04]:[-.1,.1]])),travel:Object.fromEntries(axes.map(a=>[a,[-.5,.5]]))};}
let state={step:0,n:2,inputMode:'native',blind:[makePart([101],'blind'),makePart([102],'blind')],coupled:[makePart([201,211,212,213,214],'coupled')],targets:[{name:'die1',source:211,detector:301,axis:'X',distance:1000,reference:'',scale:1,limit:'',flux:.95},{name:'die2',source:212,detector:302,axis:'X',distance:1000,reference:'',scale:1,limit:'',flux:.95}],runs:100,method:'OD',cycles:5,rays:100000};
let pickerKind='blind';
function showToast(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,2500);}
function options(role,selected){return objects.filter(o=>o.role===role).map(o=>`<option value="${o.id}" ${+selected===o.id?'selected':''}>${objectLabel(o.id)}</option>`).join('');}
function summary(){const count=k=>state[k].reduce((n,p)=>n+p.axes.length,0);$('#summary').innerHTML=`<dl><dt>盲装件</dt><dd>${state.blind.length} 组 / ${count('blind')}D</dd><dt>耦合件</dt><dd>${state.coupled.length} 组 / ${count('coupled')}D</dd><dt>目标 die</dt><dd>die1 · die2</dd><dt>宽度口径</dt><dd>RMS H</dd><dt>误差分布</dt><dd>±${state.n}σ 截断正态</dd><dt>优化方式</dt><dd>连续 · ${state.method}</dd></dl>`;}
function partHTML(p,kind){const blind=kind==='blind',native=state.inputMode==='native';return `<article class="part axis-card" data-id="${p.id}" data-kind="${kind}"><div class="part-head"><div><h3>${objectLabel(p.objects[0])}</h3><p>${p.objects.length>1?`刚体组 · ${p.objects.length} 对象 · die1—die4 同步移动`:'独立装配件'} · 示例参考坐标 / 枢轴待核对</p></div><button data-remove="${p.id}" aria-label="移除${objectLabel(p.objects[0])}">移除</button></div><div class="axis-grid">${axes.map(a=>{const active=p.axes.includes(a),ds=active?'':'disabled';return `<div class="axis-cell ${active?'':'inactive'}"><label class="axis-title"><input type="checkbox" data-axis="${a}" ${active?'checked':''}><b>${a}</b><span>${a.length===1?'mm':'deg'}</span></label>${blind&&!native?`<label class="axis-value"><span>σ</span><input type="number" min="0.000001" step="0.01" data-sigma="${a}" value="${p.sigma[a]}" ${ds} aria-label="${a} 标准差"></label><small class="range-note">${p.ranges[a].join(' / ')}</small>`:[0,1].map(e=>`<label class="axis-value"><span>${blind?(e?'Max':'Min'):(e?'正':'负')}</span><input type="number" step="0.01" ${blind?`data-range="${a}"`:`data-travel="${a}"`} data-end="${e}" value="${(blind?p.ranges:p.travel)[a][e]}" ${ds} aria-label="${a} ${blind?(e?'Max误差':'Min误差'):(e?'正行程':'负行程')}"></label>`).join('')}</div>`;}).join('')}</div></article>`;}
function parts(kind){const blind=kind==='blind';return `<section class="assembly-section"><div class="section-title"><div><h2>${blind?'盲装件':'耦合件'}</h2><p>${blind?'装入后固定 · Min / Max 为相对名义值的随机误差':'装配后可调整 · 多个 die 共享连续补偿，行程相对装配零位'}</p></div><button data-add="${kind}">＋ 添加${blind?'盲装件':'耦合件'}</button></div>${blind?`<div class="row-options"><label>输入 <select id="input-mode" aria-label="误差输入方式"><option value="native" ${state.inputMode==='native'?'selected':''}>Min / Max · 原生</option><option value="sigma" ${state.inputMode==='sigma'?'selected':''}>σ 辅助 · 对称</option></select></label><label>正态范围 <select id="truncation" aria-label="截断倍数"><option value="2" ${state.n===2?'selected':''}>±2σ · 默认</option><option value="3" ${state.n===3?'selected':''}>±3σ</option></select></label><span class="push">默认 6D · 可逐轴取消</span></div>`:''}<div class="assembly-cards">${state[kind].map(p=>partHTML(p,kind)).join('')||'<div class="empty">尚未添加组件</div>'}</div></section>`;}
function assembly(){return parts('blind')+parts('coupled')+`<details class="help"><summary>输入范围、σ 与补偿行程说明</summary><p>Min / Max 是相对名义值的误差。正态中心=(Min+Max)/2，σ=(Max−Min)/(2n)。切换 σ 助手不覆盖原范围，仅编辑某轴 σ 才使该轴对称。补偿行程将编译为评价函数约束，并逐样本检查越界；不设置离散步长。</p></details>`;}
const detectorMeta={301:{z:1000,ref:'示例全局参考 / Ref Object 0'},302:{z:1200,ref:'示例全局参考 / Ref Object 0'}};
function syncDetector(t){const m=detectorMeta[t.detector];t.distance=m.z;t.reference=m.ref;t.distanceSource='detector-local-z';t.coordinateStatus='example-unverified';return m;}
function targetHTML(t,i){const m=syncDetector(t);return `<article class="part target-card"><div class="part-head"><div class="target-label"><span class="die-tag">${t.name}</span><h3>H 向 RMS 等效角宽</h3></div></div><div class="part-body"><div class="fields"><label>源对象<select data-target="${i}" data-field="source">${options('source',t.source)}</select></label><label>专用探测面<select data-target="${i}" data-field="detector">${options('detector',t.detector)}</select></label><label>H 对应局部轴<select data-target="${i}" data-field="axis"><option ${t.axis==='X'?'selected':''}>X</option><option ${t.axis==='Y'?'selected':''}>Y</option></select></label><label>传播距离 · 探测面 Z / mm<input readonly aria-label="${t.name} 示例探测面Z" value="${m.z}"></label><div class="coordinate-note span">示例 Z · 未连接 Zemax　|　${m.ref}<br>局部 Z 输入坐标；作为传播距离的参考关系待核验。</div><label>归一化尺度 / mrad<input type="number" min="0.000001" value="${t.scale}" data-target="${i}" data-field="scale"></label><label>验收上限 / mrad<input type="number" min="0.000001" value="${t.limit}" placeholder="可选" data-target="${i}" data-field="limit"></label><label>最低名义功率保持率<input type="number" min="0.000001" max="1" step="0.01" value="${t.flux}" data-target="${i}" data-field="flux"></label></div></div></article>`;}
function targets(){return `<div class="section-title"><div><h2>目标</h2><p>每颗 die 一个专用探测面，联合优化同一组耦合件。</p></div><span class="metric-inline">q<sub>H</sub> = 1000 σ<sub>H</sub> / Z <small>mrad</small></span></div><div class="targets-grid">${state.targets.map(targetHTML).join('')}</div><details class="help"><summary>指标与最低名义功率保持率</summary><p>RMS 等效角宽使用近轴远场近似，不是 D86 或全角。最低名义功率保持率是本次接收功率相对同颗 die 冻结名义接收功率，避免截光导致虚假的宽度改善。探测器 Z 与实际传播距离的坐标关系需要核验。</p></details>`;}
function validation(){const errors=[];if(!state.blind.length)errors.push('至少添加一个盲装件');if(!state.coupled.length)errors.push('至少添加一个耦合件');for(const kind of ['blind','coupled'])for(const p of state[kind]){if(!p.axes.length)errors.push(`${objectLabel(p.objects[0])}未选择维度`);for(const a of p.axes)if(kind==='blind'){const [lo,hi]=p.ranges[a];if(!Number.isFinite(lo)||!Number.isFinite(hi)||lo>=hi)errors.push(`${objectLabel(p.objects[0])} ${a} Min须小于Max`);}else{const [lo,hi]=p.travel[a];if(!Number.isFinite(lo)||!Number.isFinite(hi)||lo>0||hi<0||lo>=hi)errors.push(`${a}行程须包含零位且下限小于上限`);}}const b=new Set(state.blind.flatMap(p=>p.objects));if(state.coupled.some(p=>p.objects.some(id=>b.has(id))))errors.push('同一对象不能同时作为独立盲装件和耦合件');for(const t of state.targets){if(!(t.distance>0&&Number.isFinite(t.distance)))errors.push(`${t.name}距离须大于0`);if(!(t.scale>0&&Number.isFinite(t.scale)))errors.push(`${t.name}尺度须大于0`);if(!(t.flux>0&&t.flux<=1))errors.push(`${t.name}能量比例须在(0,1]`);if(t.limit!==''&&!(+t.limit>0))errors.push(`${t.name}验收上限须大于0`);}if(state.targets[0].source===state.targets[1].source)errors.push('die1与die2不能映射为同一源对象');if(state.targets[0].detector===state.targets[1].detector)errors.push('两颗die应选择各自的专用探测面');if(!Number.isInteger(state.runs)||state.runs<1||state.runs>10000)errors.push('MC样本数须为1–10000整数');return errors;}
function compiled(){const lines=[`# 原生配置草稿 · 不执行 / 示例对象编号`,`STAT  Int1=0  Int2=${state.n}`];for(const p of state.blind)for(const a of p.axes)lines.push(`TNPS  Surf=1  Object=${p.objects[0]}  Code=${axes.indexOf(a)+1}  Min=${p.ranges[a][0]}  Max=${p.ranges[a][1]}`);for(const p of state.coupled)for(const a of p.axes)lines.push(`CNPS  Object=${p.objects[0]}  Code=${axes.indexOf(a)+1}  Surf=1  # 行程另编译到MF：${p.travel[a].join(' … ')}`);state.targets.forEach(t=>lines.push(`\n# ${t.name}: H=${t.axis}, L=${t.distance} mm`,`NSDD  Surf=1  Det=0  # 清空`,`NSTR  Surf=1  Src=${t.source}`,`NSDD  Surf=1  Det=${t.detector}  Pix=${t.axis==='X'?-10:-11}  Data=0  # RMS宽度`,`# 功率约束、距离尺度和行程边界：正式编译器待实现`));return lines.join('\n');}
function oldChecks(){const errors=validation();return `<section class="run-plan"><div class="section-title"><h2>运行计划</h2><span class="subtle">灵敏度分析 + Monte Carlo · 两颗 die 等权</span></div><div class="run-controls"><label>Monte Carlo 样本数<input id="runs" type="number" min="1" max="10000" value="${state.runs}"></label><label>连续补偿方法<select id="method"><option ${state.method==='OD'?'selected':''}>OD</option><option ${state.method==='DLS'?'selected':''}>DLS</option></select></label><button disabled>在副本运行 · 尚未接入</button><button id="demo-start">演示运行状态 →</button></div><div class="check-inline ${errors.length?'error':''}">${errors.length?errors.map(esc).join('；'):'✓ 表单数值通过'}<span>○ 真实模型、参考坐标、名义功率及补偿执行待校验</span></div><details class="help"><summary>指标、功率保持率与 OD / DLS 是什么？</summary><p>RMS 等效角宽采用近轴远场近似，不是 D86 或全角。首版按所选探测面 Z 读取距离；局部参考、出射零位和传播方向匹配前不能执行。</p><p>最低名义功率保持率 = 本次探测功率 / 同颗 die 冻结名义接收功率，防止截光造成虚假的光斑收窄。</p><p><b>补偿在做什么：</b>先固定本次盲装误差，再只调整选定耦合件，使 die1/die2 的联合评价函数改善。机械同组的 die 始终共用一套补偿位置。</p><p><b>OD（正交下降）：</b>不依赖数值导数，用试探搜索改善方向；适合像素化或噪声较明显的非序列目标，可作为首轮试跑方法。</p><p><b>DLS（阻尼最小二乘）：</b>通过变量微小变化估计评价函数的局部响应，适合较平滑的目标。Zemax 公差工具的 Optimize All (DLS) 先执行一轮 OD，再执行 DLS。</p><p>两者都是连续局部优化，不是机械步进，也不保证全局最优。优化循环数是每个误差样本内部的求解次数设置，不是 Monte Carlo 样本数。原生 None 则忽略补偿器，用于未补偿对照。</p></details><details><summary>原生 TDE / MFE 编译草稿</summary><pre>${esc(compiled())}</pre></details></section>`;}
let job={status:'idle',progress:0,stage:0},timer;
let stages=['准备副本与名义校验','生成随机误差','Monte Carlo 与连续补偿','汇总样本与生成报告'];let analysisMode='mc',sensComp='none';const jobs={mc:job,sensitivity:{status:'idle',progress:0,stage:0}};
function startDemo(){if(job.status==='running')return;clearInterval(timer);job={status:'running',progress:0,stage:0};go(2);timer=setInterval(()=>{job.progress=Math.min(100,job.progress+5);job.stage=Math.min(3,Math.floor(job.progress/26));if(job.progress===100){job.status='completed';clearInterval(timer);}if(state.step===2){if(job.status==='completed')render();else{const progress=$('.job-card progress');if(progress)progress.value=job.progress;const number=$('.job-top strong');if(number)number.textContent=job.progress+'%';document.querySelectorAll('.stage-grid>div').forEach((el,i)=>{el.className=i<job.stage?'done':i===job.stage?'current':'';el.querySelector('span').textContent=i<job.stage?'✓':i+1;});}}},500);}
function checks(){const running=job.status==='running',sens=analysisMode==='sensitivity',errors=validation();return `<section class="run-plan compact-plan"><div class="run-controls">${sens?`<label>端点评估方式<select id="sens-comp" ${running?'disabled':''}><option value="none" ${sensComp==='none'?'selected':''}>不补偿</option><option value="compensated" ${sensComp==='compensated'?'selected':''}>补偿后</option></select></label>`:`<label>Monte Carlo 样本数<input id="runs" type="number" min="1" max="10000" value="${state.runs}" ${running?'disabled':''}></label>`}${!sens||sensComp==='compensated'?`<label>连续补偿方法<select id="method" ${running?'disabled':''}><option ${state.method==='OD'?'selected':''}>OD</option><option ${state.method==='DLS'?'selected':''}>DLS</option></select></label>`:''}<button disabled>真实运行 · 尚未接入</button><button id="demo-start" ${running?'disabled':''}>演示${sens?'灵敏度':'Monte Carlo'}</button><button id="demo-results" ${running?'disabled':''}>查看本模式示例</button></div><div class="check-inline ${errors.length?'error':''}">${errors.length?errors.map(esc).join('；'):'✓ 表单数值通过'}<span>未连接 Zemax · 坐标、名义光学与补偿执行仍待核验</span></div><details class="help"><summary>补偿方法与两种分析模式</summary><p>补偿先固定当前盲装误差，仅调整耦合件，使两颗 die 联合评价函数改善。OD 不依赖数值导数，适合像素化或噪声较明显的 NSC 目标；DLS 使用局部变化估计改善方向，适合较平滑目标，原生 Optimize All (DLS) 先一轮 OD 再 DLS。均为连续局部搜索，不保证全局最优，也不等于 MC 样本数。</p><p>灵敏度一次只改变一个盲装轴，在 Min / Max 两端点评估；Monte Carlo 对所有盲装误差组合抽样。两模式共用装配与目标，同一时刻只有一个演示任务。</p></details></section>`;}
function sensitivityResult(){const factor=sensComp==='none'?1:.45;const rows=[['示例准直镜 A','Tx',-.1,.1,.31,.27,.36,.29],['示例整形镜 B','x',-.04,.04,.18,.21,.23,.26],['示例准直镜 A','z',-.04,.04,.09,.12,.11,.14],['示例整形镜 B','Ty',-.1,.1,.06,.08,.09,.1]];return `<section class="result-table"><div class="chart-head"><h3>灵敏度端点排序 · ${sensComp==='none'?'不补偿':'补偿后'}示例</h3><span class="demo">4 项代表性合成数据</span></div><p class="subtle">一次仅扰动一个盲装轴；表中为 Min / Max 相对名义的 Δq（mrad）。按两颗 die 最大绝对变化降序。条长不是连续扫描。</p><div class="table-wrap"><table class="sensitivity-table"><thead><tr><th>盲装件 / 轴</th><th>Min / Max</th><th>die1 Δq<br>Min / Max</th><th>die2 Δq<br>Min / Max</th><th>最大 |Δq|</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]} · ${r[1]}</td><td>${r[2]} / ${r[3]} ${r[1].length===1?'mm':'deg'}</td><td>+${(r[4]*factor).toFixed(3)} / +${(r[5]*factor).toFixed(3)}</td><td>+${(r[6]*factor).toFixed(3)} / +${(r[7]*factor).toFixed(3)}</td><td><span class="rankbar" style="width:${Math.max(...r.slice(4))*factor*180}px"></span>${(Math.max(...r.slice(4))*factor).toFixed(3)}</td></tr>`).join('')}</tbody></table></div><p class="subtle">原生分析使用端点；此示例未运行 Zemax，也不代表当前模型的敏感度排名。</p></section>`;}
function results(){const running=job.status==='running',done=job.status==='completed',sens=analysisMode==='sensitivity';return `<div class="section-title"><div><h2>运行与结果</h2><p>选择独立分析模式，共用装配与目标配置。</p></div><span class="demo">演示 · 未执行 Zemax</span></div><div class="mode-tabs"><button data-mode="mc" class="${!sens?'selected':''}" ${running?'disabled':''}>Monte Carlo 公差<small>全部盲装误差组合</small></button><button data-mode="sensitivity" class="${sens?'selected':''}" ${running?'disabled':''}>灵敏度分析<small>逐个盲装轴的 Min / Max</small></button></div>${checks()}<section class="job-card small-job"><div class="job-top"><div><span class="eyebrow">DEMO · ${sens?'SENSITIVITY':'MONTE CARLO'}</span><h3>${running?'演示运行中':done?'本模式示例完成':job.status==='cancelled'?'演示已取消':'尚未启动本模式'}</h3></div><strong>${job.progress}%</strong></div><progress max="100" value="${job.progress}" aria-label="演示进度"></progress><div class="stage-grid">${stages.map((s,i)=>`<div class="${done||i<job.stage?'done':running&&i===job.stage?'current':''}"><span>${done||i<job.stage?'✓':i+1}</span>${s}</div>`).join('')}</div>${running?'<button id="demo-cancel">取消演示</button>':''}</section>${done?(sens?sensitivityResult():`<section class="result-table"><h3>Monte Carlo 汇总 · 固定合成示例</h3><table><thead><tr><th>对象</th><th>名义 q / mrad</th><th>补偿前均值</th><th>补偿后均值</th></tr></thead><tbody><tr><td>die1</td><td>1.20</td><td>1.72</td><td>1.29</td></tr><tr><td>die2</td><td>1.26</td><td>1.81</td><td>1.35</td></tr></tbody></table><p class="subtle">示例 100 样本 / 97 有效 / 3 失败：功率不足 2、越界 1。与当前表单无计算关系。</p><h3>共享耦合件 · 最大行程利用率（示例）</h3><div class="utilization">${[['x',42],['y',28],['z',76],['Tx',35],['Ty',61],['Tz',18]].map(([a,n])=>`<div><span>${a}</span><meter min="0" max="100" value="${n}"></meter><b>${n}%</b></div>`).join('')}</div></section>`):'<div class="empty result-empty">运行演示或查看本模式示例后，结果将在此显示。</div>'}`;}
function render(){const step=state.step;$('#steps').innerHTML=names.map((n,i)=>`<button class="step ${i===step?'active':''}" data-step="${i}" ${i===step?'aria-current="page"':''}><em>0${i+1}</em><div><b>${n}</b><small>${descriptions[i]}</small></div></button>`).join('');$('#step-content').innerHTML=step===0?assembly():step===1?targets():results();$('#previous').disabled=step===0;$('#next').textContent=step===0?'目标 →':step===1?'运行与结果 →':'导出设计 YAML ↓';$('#footer-note').textContent='设计原型 · 示例数据 · 未执行 Zemax';summary();}
function go(step){state.step=step;render();$('.editor').scrollTop=0;}
$('#steps').addEventListener('click',e=>{const b=e.target.closest('[data-step]');if(b)go(+b.dataset.step);});
$('#previous').onclick=()=>go(Math.max(0,state.step-1));$('#next').onclick=()=>{if(state.step<2)go(state.step+1);else exportDraft();};
$('#step-content').addEventListener('click',e=>{const mode=e.target.closest('[data-mode]');if(mode&&job.status!=='running'){jobs[analysisMode]=job;analysisMode=mode.dataset.mode;job=jobs[analysisMode];stages=analysisMode==='mc'?['准备副本与名义校验','生成随机误差','Monte Carlo 与连续补偿','汇总样本与生成报告']:['准备名义状态','逐轴 Min / Max','端点评价','汇总灵敏度排序'];render();}const add=e.target.closest('[data-add]');if(add)openPicker(add.dataset.add);if(e.target.closest('#demo-start'))startDemo();if(e.target.closest('#demo-cancel')){clearInterval(timer);job.status='cancelled';render();}if(e.target.closest('#demo-results')&&job.status!=='running'){clearInterval(timer);job={status:'completed',progress:100,stage:3};go(2);}const remove=e.target.closest('[data-remove]');if(remove){const c=remove.closest('[data-kind]');state[c.dataset.kind]=state[c.dataset.kind].filter(p=>p.id!==remove.dataset.remove);render();}});
$('#step-content').addEventListener('change',e=>{const el=e.target;if(el.id==='sens-comp'){sensComp=el.value;if(job.status==='completed')job={status:'idle',progress:0,stage:0};render();return;}if(el.id==='input-mode'){state.inputMode=el.value;for(const p of state.blind)for(const a of axes)p.sigma[a]=(p.ranges[a][1]-p.ranges[a][0])/(2*state.n);render();return;}if(el.id==='truncation'){state.n=+el.value;for(const p of state.blind)for(const a of axes)p.sigma[a]=(p.ranges[a][1]-p.ranges[a][0])/(2*state.n);render();return;}const card=el.closest('[data-id]');if(card){const p=state[card.dataset.kind].find(p=>p.id===card.dataset.id);if(el.dataset.axis){p.axes=el.checked?[...p.axes,el.dataset.axis]:p.axes.filter(a=>a!==el.dataset.axis);render();}if(el.dataset.sigma){p.sigma[el.dataset.sigma]=el.value===''?NaN:+el.value;p.ranges[el.dataset.sigma]=[-state.n*p.sigma[el.dataset.sigma],state.n*p.sigma[el.dataset.sigma]];render();}if(el.dataset.range){p.ranges[el.dataset.range][+el.dataset.end]=el.value===''?NaN:+el.value;p.sigma[el.dataset.range]=(p.ranges[el.dataset.range][1]-p.ranges[el.dataset.range][0])/(2*state.n);render();}if(el.dataset.travel){p.travel[el.dataset.travel][+el.dataset.end]=el.value===''?NaN:+el.value;summary();}}if(el.dataset.target!==undefined){const t=state.targets[+el.dataset.target],f=el.dataset.field;t[f]=['reference','axis','limit'].includes(f)?el.value:el.value===''?NaN:+el.value;if(f==='detector'){syncDetector(t);render();}}if(el.id==='runs'){state.runs=+el.value;render();}if(el.id==='method'){state.method=el.value;summary();}});
function openPicker(kind){pickerKind=kind;$('#picker-title').textContent=`添加${kind==='blind'?'盲装件':'耦合件'}`;$('#group-mode').hidden=kind==='blind';$('#object-search').value='';$('#picker-error').textContent='';paintPicker();$('#picker').showModal();}
function paintPicker(){const q=$('#object-search').value.toLowerCase();const used=new Set([...state.blind,...state.coupled].flatMap(p=>p.objects));$('#picker-list').innerHTML=objects.filter(o=>o.role!=='detector'&&(pickerKind==='coupled'||o.role==='lens')).filter(o=>(objectLabel(o.id)+o.type).toLowerCase().includes(q)).map(o=>`<label class="pick-row ${used.has(o.id)?'disabled':''}"><input type="checkbox" value="${o.id}" ${used.has(o.id)?'disabled':''}><div><b>${objectLabel(o.id)}</b><small>${o.type}${used.has(o.id)?' · 已添加':''}</small></div></label>`).join('');}
$('#object-search').oninput=paintPicker;$('#picker-close').onclick=()=>$('#picker').close();$('#add-selected').onclick=()=>{const ids=[...$('#picker-list').querySelectorAll('input:checked')].map(x=>+x.value);if(!ids.length){$('#picker-error').textContent='请至少选择一个对象。';return;}if(pickerKind==='coupled'&&$('#rigid').checked)state.coupled.push(makePart(ids,'coupled'));else ids.forEach(id=>state[pickerKind].push(makePart([id],pickerKind)));$('#picker').close();render();};
function exportDraft(){const errors=validation();if(errors.length){$('#footer-note').textContent='请先修正：'+errors[0];return;}const y=['# 设计原型导出；不能交给现有Tx执行器','schemaVersion: tx-ui-prototype-draft-1','status: design-only','engine: zemax-native-tolerancing','executionTarget: copy-system','model: {modelId: null, expectedRevision: null}',`statistics: {distribution: truncated-normal, truncationSigma: ${state.n}, sigmaMeaning: parent-normal-before-truncation}`];for(const kind of ['blind','coupled']){y.push(kind+'Parts:');for(const p of state[kind]){y.push('  - exampleObjectIndices: '+JSON.stringify(p.objects),'    enabledDofs: '+JSON.stringify(p.axes));if(kind==='blind')y.push('    errorRange: '+JSON.stringify(Object.fromEntries(p.axes.map(a=>[a,{min:p.ranges[a][0],max:p.ranges[a][1]}]))));else y.push('    travel: '+JSON.stringify(Object.fromEntries(p.axes.map(a=>[a,{min:p.travel[a][0],max:p.travel[a][1]}]))));}}y.push('targets:','  metric: rms-h-over-detector-z-paraxial','  fluxMeaning: fraction-of-frozen-nominal-received-power','  dies:');for(const t of state.targets)syncDetector(t);for(const t of state.targets)y.push('    - '+JSON.stringify(t));y.push(`analysis: {mode: ${analysisMode}, monteCarloRuns: ${analysisMode==='mc'?state.runs:0}, sensitivityCompensation: ${sensComp}, compensation: {mode: continuous, method: ${state.method}}}`);const blob=new Blob([y.join('\n')+'\n'],{type:'application/yaml'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='tx-native-design-draft.yaml';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);showToast('已导出设计 YAML；真实对象绑定仍待完成。');}
$('#save-draft').onclick=()=>{try{localStorage.setItem(key,JSON.stringify(state));$('#save-note').textContent='已保存原型草稿 · '+new Date().toLocaleTimeString();}catch{showToast('浏览器未允许保存，请导出 YAML。');}};
try{const s=JSON.parse(localStorage.getItem(key));if(s?.blind&&s?.coupled&&s?.targets?.length===2)state=s;}catch{}
const themeKey='optdsh-tx-prototype-theme';function applyTheme(t){document.body.dataset.theme=t;$('#theme-toggle').textContent=t==='dark'?'☀ 浅色':'☾ 深色';try{localStorage.setItem(themeKey,t);}catch{}}let initialTheme='light';try{initialTheme=localStorage.getItem(themeKey)||'light';}catch{}applyTheme(initialTheme);$('#theme-toggle').onclick=()=>applyTheme(document.body.dataset.theme==='dark'?'light':'dark');
function open(){render();$('#workflow').showModal();}$('#launch').onclick=open;$('#launch-side').onclick=open;$('#close').onclick=()=>$('#workflow').close();
render();if(new URLSearchParams(location.search).get('closed')!=='1')$('#workflow').showModal();
